from collections import Counter,defaultdict
def comps(g,val,diag=True):
    h=len(g); w=len(g[0]); seen=set(); cs=[]
    for r,c in itertools.product(range(h),range(w)):
        if g[r][c]==val and (r,c) not in seen:
            st=[(r,c)]; seen.add((r,c)); s=[]; size=0
            while st:
                y,x=st.pop(); size+=1
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==val and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
            cs.append(size)
    return sorted(cs)
